import{z as i,x as B,o as r,c as p,q as l,j as n,D as s,d as e,s as t,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"龙书 Aho–Sethi–Ullman","description":"","frontmatter":{"title":"龙书 Aho–Sethi–Ullman","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dragon-book.md","filePath":"cs/dragon-book.md","lastUpdated":1791063341000}'),h={name:"cs/dragon-book.md"};function d(c,a,m,f,C,u){const o=B("Mermaid");return r(),p("div",null,[a[2]||(a[2]=l('<h1 id="龙书-aho–sethi–ullman" tabindex="-1">龙书 Aho–Sethi–Ullman <a class="header-anchor" href="#龙书-aho–sethi–ullman" aria-label="Permalink to &quot;龙书 Aho–Sethi–Ullman&quot;">​</a></h1><div class="epigraph"><p>编译是一串通行证：词法、语法、语义、中间代码、优化、目标代码；前端用形式语言，后端对着 ISA。</p><footer>—— Aho, Sethi and Ullman, Compilers: Principles, Techniques, and Tools（龙书）</footer></div><p><a href="/cs/patterson-hennessy">上一课</a>附录对照了体系结构教材。附录对照，不插入主干。主干已在<a href="/cs/patterson-hennessy">编译器通行证</a>、<a href="/cs/regex-lexer">正则与词法</a>、<a href="/cs/lr-shift-reduce">LR 与移进归约</a>、<a href="/cs/ssa-form">SSA</a>、<a href="/cs/regalloc-color">寄存器分配着色</a>里按通行证取用；这里对照 <strong>龙书的问题</strong>：如何把编译写成可证明的前端加可工程的后端。不重做 FIRST/FOLLOW 表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>主干编译课接在 NPC 之后、OS 之前，对象是把高级语言落到 ABI。龙书的缺口是把自动机、文法、数据流做成同一条生产线。1986 初版与后版增加了更多优化；主干只取通行证骨架与 SSA 一代的数据流，不把全书练习插进课序。</p><p><span class="marginnote">龙书不是唯一编译教材。Appel、Cooper/Torczon 等是对照。主干用龙书当「通行证与形式化前端」的文献锚，不排斥 SSA 在后版中的位置。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>词法：正则 → 自动机。语法：CFG → LL/LR。语义：符号表与类型。IR：三地址。优化：数据流不动点。后端：选择、分配、调度。主干<a href="/cs/peephole">窥孔</a>与<a href="/cs/abi-codegen">ABI</a>已接 ISA 课。附录对照这本书为何能当「编译课的出处」，而不是再讲一遍活跃变量方程。</p>',8)),(r(),n(A,null,{default:s(()=>[t(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%E8%AF%AD%E8%A8%80%22%5D%20--%3E%20FE%5B%22%E5%BD%A2%E5%BC%8F%E5%8C%96%E5%89%8D%E7%AB%AF%22%5D%0A%20%20FE%20--%3E%20IR%5B%22%E4%B8%AD%E9%97%B4%E8%A1%A8%E7%A4%BA%22%5D%0A%20%20IR%20--%3E%20BE%5B%22%E5%AF%B9%E7%9D%80%20ISA%20%E7%9A%84%E5%90%8E%E7%AB%AF%22%5D%0A%20%20FE%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%20%E9%80%9A%E8%A1%8C%E8%AF%81%E5%90%84%E8%AF%BE%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("形式化前端使「语法错」有定义；数据流使优化有不动点而不是补丁列表。这与 Knuth 分析算法、Patterson 量化硬件同一精神：对象可推理。运行时与 GC 在主干"),E("a",{href:"/cs/runtime-gc"},"运行时与 GC 直觉"),e("，龙书也谈，但不插入本附录当新课。")],-1)),(r(),n(A,null,{default:s(()=>[t(o,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20LR%0A%20%20LEX%5B%22%E8%AF%8D%E6%B3%95%E9%80%9A%E8%A1%8C%E8%AF%81%22%5D%20--%3E%7C%22%E6%AD%A3%E5%88%99%E8%AF%AD%E8%A8%80%20%2B%20%E6%9C%89%E9%99%90%E8%87%AA%E5%8A%A8%E6%9C%BA%22%7C%20TOK%5B%22%E8%AE%B0%E5%8F%B7%E6%B5%81%22%5D%0A%20%20PAR%5B%22%E8%AF%AD%E6%B3%95%E9%80%9A%E8%A1%8C%E8%AF%81%22%5D%20--%3E%7C%22%E4%B8%8A%E4%B8%8B%E6%96%87%E6%97%A0%E5%85%B3%E6%96%87%E6%B3%95%20%2B%20LL%2FLR%22%7C%20AST%5B%22%E8%AF%AD%E6%B3%95%E6%A0%91%22%5D%0A%20%20SEM%5B%22%E8%AF%AD%E4%B9%89%E9%80%9A%E8%A1%8C%E8%AF%81%22%5D%20--%3E%7C%22%E5%B1%9E%E6%80%A7%E4%B8%8E%E7%B1%BB%E5%9E%8B%E7%B3%BB%E7%BB%9F%22%7C%20SYM%5B%22%E7%AC%A6%E5%8F%B7%E8%A1%A8%E6%A3%80%E6%9F%A5%22%5D%0A%20%20OPT%5B%22%E4%BC%98%E5%8C%96%E9%80%9A%E8%A1%8C%E8%AF%81%22%5D%20--%3E%7C%22%E6%A0%BC%E4%B8%8E%E4%B8%8D%E5%8A%A8%E7%82%B9%E6%95%B0%E6%8D%AE%E6%B5%81%22%7C%20IMP%5B%22%E6%9B%B4%E4%BC%98%20IR%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">术语翻译：「通行证」（pass）就是编译器流水线上的一道独立工序——每道只做一件事，吃上一道的输出、产出下一段输入。说「编译器有几十个 pass」，意思是它由几十道可单独替换的小工序拼成，而不是一整坨代码。</span></p><p><span class="marginnote">直觉类比：前端三道形式化检查像海关三查——词法先验护照真伪（把字符切成记号），语法再验报关单格式（记号是否组成合法语句），语义最后核对品名与税号（类型是否匹配）。每一查都有一套精确规则，所以「哪里错」有定义。</span></p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>若按龙书章节插在数据结构中间，自动机会打断树与图。主干把形式语言放在编译课，前面只用正则当工具。附录只对照教材作为通行证的文献。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把「龙书封面」当引用。下一篇对照 Tanenbaum《现代操作系统》如何把进程、内存、文件、I/O 收成教材，主干 OS 课已经按映像与系统调用走过。</p><p><span class="marginnote">常见误区：初学者容易以为编译器是一个从头跑到尾的整体程序，出了错只能整体调试。实际上通行证结构保证每道 pass 输入输出都有明确定义，语法错定位在解析器、慢代码定位在优化器——这也是龙书把它写成「生产线」的工程意义。</span></p><p>属性文法与语法制导翻译是前端语义的教材写法；主干<a href="/cs/typecheck">类型检查</a>已取用检查，不把 AG 公式插进课序。</p><p>对照结束应回到主干<a href="/cs/compiler-passes">编译器通行证</a>。龙书目录不替换知识树。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照龙书：编译 = 通行证，前端形式化，后端对 ISA。</li><li>主干编译各课已按此骨架取用。</li><li>不按全书练习重排知识树。</li><li>出处：Aho, Sethi and Ullman, <em>Compilers: Principles, Techniques, and Tools</em>。</li></ul>',11))])}const F=i(h,[["render",d]]);export{D as __pageData,F as default};
